-- 0008_restore_strong_history.sql
-- Restores the two workouts taken over from the Strong screenshots (seed/history.json):
-- DAY1 28 September 2026 and DAY2 2 October 2026, with all exercises and sets.
-- Fixed ids: existing rows are overwritten with the original values and undeleted, nothing is duplicated.
-- Sets get completed_at = end of the workout, so they count in the Stats tab.
-- updated_at = now(), so the restored state wins against older states on all devices (last write wins).
-- The template link is kept only if the template still exists.
-- Run in the Neon SQL Editor (owner access; user_id comes from private.app_owner). Idempotent.

insert into public.workout (id, user_id, template_id, template_name_snapshot, started_at, finished_at, note, created_at, updated_at, deleted_at)
select w.id, o.user_id, (select t.id from public.template t where t.id = w.template_id), w.template_name_snapshot, w.started_at, w.finished_at, w.note, w.started_at, now(), null
from (select user_id from private.app_owner limit 1) o,
     jsonb_to_recordset('[{"id":"01e39cfd-d391-540c-a73a-3eff061f93a9","template_id":"30a6cb05-9ea8-5d39-9a00-7c68b66647cd","template_name_snapshot":"DAY1","started_at":"2026-09-28T09:37:00+02:00","finished_at":"2026-09-28T10:35:00+02:00","note":"Übernommen aus Strong (Screenshot)"},{"id":"cb03f7f6-8442-56d9-8e02-e04cf839b759","template_id":"4af480e8-7a8d-5fd9-ae69-998bcf30f86a","template_name_snapshot":"DAY2","started_at":"2026-10-02T10:45:00+02:00","finished_at":"2026-10-02T11:50:00+02:00","note":"Übernommen aus Strong (Screenshot)"}]'::jsonb)
       as w(id uuid, template_id uuid, template_name_snapshot text, started_at timestamptz, finished_at timestamptz, note text)
on conflict (id) do update set
  template_id = excluded.template_id, template_name_snapshot = excluded.template_name_snapshot,
  started_at = excluded.started_at, finished_at = excluded.finished_at, note = excluded.note,
  updated_at = excluded.updated_at, deleted_at = null;

