  (select count(*) from public.workout_set s join public.workout_exercise e on e.id = s.workout_exercise_id
    where e.workout_id in ('01e39cfd-d391-540c-a73a-3eff061f93a9','cb03f7f6-8442-56d9-8e02-e04cf839b759') and s.deleted_at is null) as sets;
